# -*- coding: utf-8 -*-
import numpy as np
import matplotlib.pyplot as plt


def plot_hist_with_bin_width(values, bin_width):
    """
    values: 숫자 리스트 (list, np.array 모두 가능)
    bin_width: bin 구간 크기 (예: 0.5, 1, 5 등)

    예)
        plot_hist_with_bin_width([1,2,3,4,5,6,7], bin_width=1)
    """
    values = np.asarray(values, dtype=float)

    if values.size == 0:
        raise ValueError("values 리스트가 비어 있습니다.")

    if bin_width <= 0:
        raise ValueError("bin_width는 0보다 커야 합니다.")

    v_min = values.min()
    v_max = values.max()

    # bin 경계 계산
    # 예: v_min=1.2, v_max=9.7, bin_width=1.0
    # -> 1.0, 2.0, ..., 10.0 이런 식으로 생성
    start = np.floor(v_min / bin_width) * bin_width
    stop  = np.ceil(v_max / bin_width) * bin_width

    bins = np.arange(start, stop + bin_width, bin_width)

    plt.figure()
    plt.hist(values, bins=bins)
    plt.xlabel("Value")
    plt.ylabel("Count")
    plt.title(f"Histogram (bin width = {bin_width})")
    plt.grid(True)
    plt.show()


